import 'package:flutter/material.dart';
import 'package:priceshield/core/services/priceshield_api_client.dart';
import 'package:priceshield/features/complaints/presentation/screens/complaint_screen.dart';
class ScanResultScreen extends StatefulWidget { const ScanResultScreen({super.key, required this.name, required this.barcode, required this.mrp, required this.charged}); final String name, barcode; final int mrp, charged; @override State<ScanResultScreen> createState() => _ScanResultScreenState(); }
class _ScanResultScreenState extends State<ScanResultScreen> {
  final String _requestId = 'scan-${DateTime.now().microsecondsSinceEpoch}';
  @override void initState() { super.initState(); _save(); }
  Future<void> _save() async { if (!priceShieldApi.isConfigured) return; try { await priceShieldApi.createScan(barcode: widget.barcode, productName: widget.name, mrp: widget.mrp, chargedPrice: widget.charged, clientRequestId: _requestId); } on PriceShieldApiException catch (error) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Scan was not saved: ${error.message}'))); } }
  @override Widget build(BuildContext context) { final overcharged = widget.charged > widget.mrp; return Scaffold(appBar: AppBar(title: const Text('Scan Result')), body: Padding(padding: const EdgeInsets.all(20), child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [Card(color: overcharged ? Colors.red.shade50 : Colors.green.shade50, child: Padding(padding: const EdgeInsets.all(20), child: Text(overcharged ? 'Overcharged by ₹${widget.charged - widget.mrp}' : 'This price is within MRP', style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold))),), const SizedBox(height: 16), Text(widget.name, style: Theme.of(context).textTheme.titleLarge), Text('Barcode: ${widget.barcode}'), Text('MRP: ₹${widget.mrp}'), Text('Charged price: ₹${widget.charged}'), const Spacer(), if (overcharged) FilledButton(onPressed: () => Navigator.push(context, MaterialPageRoute(builder: (_) => ComplaintScreen(name: widget.name, barcode: widget.barcode, mrp: widget.mrp, charged: widget.charged))), child: const Text('File a complaint'))]))); }
}
